              console.log(`  ${chalk.cyan(q.agentId)}  ${chalk.gray(q.agentName)}`);
              console.log(`    waiting: ${wait}s${taskStr}`);
            }
          }
        });
      } catch (err) {
        error("Failed to get agent status", err);
        process.exit(EXIT_CODES.ERROR);
      }
