/**
 * Tests for the WebSocket polyfill utility.
 *
 * Verifies that the CLI WebSocket utility exports a working WebSocket
 * constructor regardless of Node version (uses `ws` package as fallback
 * when globalThis.WebSocket is unavailable, i.e. Node < 22).
 *
 * Task: @01KK617H896Z5RHSCVA51G9QFQ
 * Spec: @cli-agent-commands
 */

import { describe, it, expect } from "vitest";
import { WebSocket } from "../src/cli/websocket.js";

describe("cli/websocket polyfill", () => {
  it("exports a WebSocket constructor", () => {
    expect(typeof WebSocket).toBe("function");
  });

  it("can create a WebSocket instance that connects", async () => {
    // Use the ws Server to verify the exported WebSocket can establish a connection
    const { WebSocketServer } = await import("ws");
    const { createServer } = await import("node:http");

    const server = createServer();
    const wss = new WebSocketServer({ server });
    let serverReceived: string | undefined;

    wss.on("connection", (ws) => {
      ws.on("message", (data) => {
        serverReceived = data.toString();
        ws.send("pong");
      });
    });

    await new Promise<void>((resolve) => server.listen(0, resolve));
    const port = (server.address() as { port: number }).port;

    try {
      const ws = new WebSocket(`ws://localhost:${port}`);
      const result = await new Promise<string>((resolve, reject) => {
        const timeout = setTimeout(() => reject(new Error("timeout")), 5000);
        ws.onopen = () => {
          ws.send("ping");
        };
        ws.onmessage = (event: MessageEvent) => {
          clearTimeout(timeout);
          resolve(event.data as string);
          ws.close();
        };
        ws.onerror = () => {
          clearTimeout(timeout);
          reject(new Error("WebSocket error"));
        };
      });

      expect(result).toBe("pong");
      expect(serverReceived).toBe("ping");
    } finally {
      wss.close();
      server.close();
    }
  });
});

