/**
 * WebSocket constructor that works on Node 18+.
 *
 * Node 22+ ships a global WebSocket. Older versions need the `ws` package.
 * We detect at import time and re-export whichever is available, keeping
 * the call-site identical (`new WebSocket(url)`).
 */

// eslint-disable-next-line @typescript-eslint/no-require-imports
const WS: typeof WebSocket =
  typeof globalThis.WebSocket !== "undefined"
    ? globalThis.WebSocket
    : (await import("ws")).default as unknown as typeof WebSocket;

export { WS as WebSocket };

